import{_ as t}from"./chunks/11-settings.B_GZgwvL.js";import{_ as a,o as i,c as s,a3 as n}from"./chunks/framework.BGhsAJMQ.js";const b=JSON.parse('{"title":"Agent config & updates","description":"","frontmatter":{},"headers":[],"relativePath":"ops/agent.md","filePath":"ops/agent.md","lastUpdated":1793798735000}'),d={name:"ops/agent.md"};function o(l,e,r,c,h,p){return i(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="agent-config-updates" tabindex="-1">Agent config &amp; updates <a class="header-anchor" href="#agent-config-updates" aria-label="Permalink to &quot;Agent config &amp; updates&quot;">​</a></h1><p>Install an Agent on every host you want to browse; it dials out to the Hub. Install steps: <a href="/filebox/guide/install-agent">Install Agent</a>.</p><h2 id="state-and-config" tabindex="-1">State and config <a class="header-anchor" href="#state-and-config" aria-label="Permalink to &quot;State and config&quot;">​</a></h2><ul><li>Config file: <code>agent.toml</code> (created by <code>--init-config</code>, mode 0600).</li><li>State directory defaults under the system data dir as <code>filebox</code> (override with <code>FILEBOX_AGENT_DATA_DIR</code>).</li><li>Roots, pins, and collections are pushed from the UI and persisted; bad updates do not wipe the last good config.</li><li>After disconnects it reconnects indefinitely with a stable identity — no duplicate sidebar entries.</li><li>Multiple instances must use different <code>FILEBOX_AGENT_DATA_DIR</code> values.</li></ul><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Meaning</th></tr></thead><tbody><tr><td><code>FILEBOX_AGENT_HUB</code></td><td>Hub URL (<code>https://</code> / <code>wss://</code>)</td></tr><tr><td><code>FILEBOX_AGENT_TOKEN</code></td><td>Agent token</td></tr><tr><td><code>FILEBOX_AGENT_NAME</code></td><td>Sidebar display name</td></tr><tr><td><code>FILEBOX_AGENT_DATA_DIR</code></td><td>State directory</td></tr><tr><td><code>FILEBOX_AGENT_AI_AGENTS_ENABLED</code></td><td>Enable or disable AI Agents on this Agent</td></tr><tr><td><code>FILEBOX_AGENT_AI_AGENTS_BACKEND</code></td><td>Lock AI Agents to a backend kind</td></tr><tr><td><code>FILEBOX_AGENT_HC</code></td><td>Explicit hc executable path (experimental backend; otherwise searches PATH)</td></tr><tr><td><code>FILEBOX_ALLOW_INSECURE_HUB</code></td><td>Allow plaintext Hub (dev only)</td></tr><tr><td><code>FILEBOX_AGENT_SOFFICE</code> / <code>_DIR</code></td><td>LibreOffice (optional)</td></tr><tr><td><code>FILEBOX_AGENT_STATS_TTL_SECS</code></td><td>sysinfo cache TTL (default 60)</td></tr><tr><td><code>FILEBOX_AGENT_DIR_CACHE_RESTAT_COOLDOWN_MS</code></td><td>Directory cache re-stat cooldown</td></tr></tbody></table><p>Office-related limits: <a href="./office">Office preview</a>.</p><h2 id="experimental-hc-backend" tabindex="-1">Experimental hc backend <a class="header-anchor" href="#experimental-hc-backend" aria-label="Permalink to &quot;Experimental hc backend&quot;">​</a></h2><p>Install <a href="https://github.com/herdrdev/herdr-core#install" target="_blank" rel="noreferrer">herdr-core</a> on the Agent machine and make <code>hc</code> available to the Filebox Agent. Only local live terminals explicitly labelled <code>fb=&lt;name&gt;</code> or <code>filebox=&lt;name&gt;</code> are included. Choose the name shown in Filebox for each terminal:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --label</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fb=frontend</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --label</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Filebox=backend</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> label</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> t7</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fb=review</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # connect or rename an existing terminal</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> label</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> t7</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fb=</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # remove this label to revoke access</span></span></code></pre></div><p>Use the actual terminal address instead of <code>t7</code>, and your program instead of <code>claude</code>, starting each terminal in its working directory. A labelled terminal may run a coding agent, a shell or another program; Filebox does not classify it. Label keys are case-insensitive in Filebox (<code>fb</code>, <code>FB</code>, <code>filebox</code>, <code>Filebox</code>, <code>FILEBOX</code>); values are user-chosen names, not fixed codes. Empty/blank values do not opt in. The original <code>filebox=ai-agent</code> marker keeps the hc terminal name. If both keys exist, <code>fb</code> supplies the display name. IDs remain visible and identify all operations, even for duplicate or changed names. To revoke access, remove all supported labels using their exact original capitalization, e.g. <code>hc label t7 Filebox=</code> for <code>Filebox=backend</code>.</p><p>Select <strong>hc (experimental)</strong> in Agent Settings; automatic selection still prefers Herdr when both are installed. <code>FILEBOX_AGENT_AI_AGENTS_BACKEND=hc</code> locks the selection. hc uses the Agent process&#39;s hc session/config environment; <code>hc connect</code> can start its local core automatically. Status requires the program&#39;s OSC 7501 reports; otherwise it is Unknown. Prompt review remains unchanged. Unlabelled, finished and remote-machine terminals are excluded. Cancellation does not retract a prompt already accepted by hc; inspect output before retrying. Tested with hc 0.1.17, API generation 1.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --update</span></span></code></pre></div><p>Verifies checksums and replaces in place. Prefer upgrading with Hub and frontend major versions together.</p><h2 id="optional-capability-switches" tabindex="-1">Optional capability switches <a class="header-anchor" href="#optional-capability-switches" aria-label="Permalink to &quot;Optional capability switches&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Where to configure</th></tr></thead><tbody><tr><td>Office preview</td><td><a href="./office">Office preview</a></td></tr><tr><td>Transfer</td><td>Capability <code>temp_upload</code>; rules in <a href="/filebox/features/transfer">Transfer</a></td></tr></tbody></table><p>Confirm connection status and enabled roots in UI <strong>Settings</strong>:</p><p><img src="`+t+'" alt="Settings"></p>',19)])])}const f=a(d,[["render",o]]);export{b as __pageData,f as default};
